private void restartService(){
  try {
    if (foregroundAllowed) {
      Intent intent=getIntent(context,serviceClass,DownloadService.ACTION_RESTART);
      Util.startForegroundService(context,intent);
    } else {
      Intent intent=getIntent(context,serviceClass,DownloadService.ACTION_INIT);
      context.startService(intent);
    }
  } catch (NullPointerException | IllegalStateException e) {
    Log.w(TAG, "Failed to restart DownloadService (null context/serviceClass or service not allowed in foreground).", e);
  } catch (IllegalStateException e) {
    Log.w(TAG, "Failed to restart DownloadService (process is idle).", e);
  }
}
